"""Tracks the sequence of handoffs a parcel has been through."""
from __future__ import annotations

from datetime import datetime
from typing import List, Optional

from models import HandoffRecord


class ChainOfCustodyError(Exception):
    """Raised when a handoff record would break continuity of custody."""


class ChainOfCustody:
    """The ordered history of handoffs for a single parcel."""

    def __init__(self, parcel_id: str, initial_holder_id: str) -> None:
        self.parcel_id = parcel_id
        self._initial_holder_id = initial_holder_id
        self._records: List[HandoffRecord] = []

    @property
    def records(self) -> List[HandoffRecord]:
        return list(self._records)

    def current_holder_id(self) -> str:
        """The courier currently holding the parcel."""
        if not self._records:
            return self._initial_holder_id
        return self._records[-1].to_courier_id

    def last_timestamp(self) -> Optional[datetime]:
        if not self._records:
            return None
        return self._records[-1].timestamp

    def add_record(self, record: HandoffRecord) -> None:
        """Append a new handoff, enforcing continuity of custody.

        The handoff must be for this parcel, must originate from
        whoever currently holds it, and must not be timestamped
        before the previous handoff in the chain.
        """
        if record.parcel_id != self.parcel_id:
            raise ChainOfCustodyError(
                f"record is for parcel {record.parcel_id!r}, not {self.parcel_id!r}"
            )
        expected_holder = self.current_holder_id()
        if record.from_courier_id != expected_holder:
            raise ChainOfCustodyError(
                f"parcel {self.parcel_id} is held by {expected_holder!r}, "
                f"not {record.from_courier_id!r}"
            )
        last_ts = self.last_timestamp()
        if last_ts is not None and record.timestamp < last_ts:
            raise ChainOfCustodyError(
                "handoff timestamp precedes the previous handoff in the chain"
            )
        self._records.append(record)
